class EngineRuntimeIntegrationTest {
    private static PostgreSQLContainer postgres;
    @DynamicPropertySource static void database(DynamicPropertyRegistry p){String external=System.getenv("TEST_DATABASE_URL");if(external!=null&&!external.isBlank()){p.add("spring.datasource.url",()->external);p.add("spring.datasource.username",()->System.getenv().getOrDefault("TEST_DATABASE_USER","mango"));p.add("spring.datasource.password",()->System.getenv().getOrDefault("TEST_DATABASE_PASSWORD","mango_local_only"));}else{postgres=new PostgreSQLContainer(DockerImageName.parse("postgres:17.11-alpine@sha256:b0f9560a2de083e2cc7382e75f808c7381a32852a7ec49117deedb300e552b24").asCompatibleSubstituteFor("postgres"));postgres.start();p.add("spring.datasource.url",postgres::getJdbcUrl);p.add("spring.datasource.username",postgres::getUsername);p.add("spring.datasource.password",postgres::getPassword);}}
    @Autowired Db db;@Autowired Json json;@Autowired Commands commands;@Autowired GameService games;@Autowired BoardRuntimeService boards;@Autowired SandboxService sandboxes;@Autowired ScenarioService scenarios;@Autowired SceneService scenes;
    private record Fixture(UUID version,UUID room,UUID game,List<UUID> users,Map<String,Object> definition){}
    private UUID user(){UUID id=UUID.randomUUID();db.update("insert into app_user(id,email,display_name,password_hash) values(?,?,?,'unused')",id,id+"@engine.invalid","시험 참가자");db.update("insert into player_activity(user_id,kind) values(?,'IDLE')",id);return id;}
    private Fixture start(Map<String,Object> definition,int count,boolean test){return commands.transaction(()->{var people=new ArrayList<UUID>();for(int i=0;i<count;i++)people.add(user());UUID sid=UUID.randomUUID(),version=UUID.randomUUID(),room=UUID.randomUUID();db.update("insert into scenario(id,slug,owner_id) values(?,?,?)",sid,"engine-"+sid,people.getFirst());db.update("insert into scenario_version(id,scenario_id,version,status,definition,presentation) values(?,?,1,'DRAFT',?::jsonb,?::jsonb)",version,sid,json.write(definition),json.write(definition.getOrDefault("presentation",obj("scenes",List.of()))));db.update("insert into room(id,scenario_version_id,host_id,visibility,mode,capacity,is_test) values(?,?,?,'INVITE','TEXT',?,?)",room,version,people.getFirst(),count,test);for(int i=0;i<count;i++){UUID uid=people.get(i);db.update("insert into room_participant(room_id,user_id,ready,joined_at) values(?,?,true,?)",room,uid,Instant.now().plusMillis(i));db.update("update player_activity set kind='ROOM',reference_id=? where user_id=?",room,uid);}UUID game=UUID.fromString(games.start(room,people.getFirst()).get("gameId").toString());return new Fixture(version,room,game,people,definition);});}
    private Map<String,Object> boardDefinition(String type){return obj("gameType",type,"engineId",type.equals("YACHT")?"yacht-v1":"tabletop-v1","playerCount",2,"supportedPlayerCounts",List.of(2,3,4),"tabletop",obj("objects",List.of(),"decks",List.of(obj("id","deck","name","덱","x",0,"y",0,"cards",List.of(obj("id","private-card","name","비밀 카드","text","상대에게 보이면 안 되는 카드","assetId",UUID.randomUUID().toString()))))));}
    private long revision(UUID game,UUID user){return ((Number)boards.snapshot(game,user).get("stateVersion")).longValue();}
    @Test void actualBoardUsesSeatsStaleProtectionAndAssetPermissions(){
        var f=start(boardDefinition("TABLETOP"),2,true);UUID owner=f.users.getFirst(),other=f.users.get(1);String asset=str(objects(objects(map(f.definition.get("tabletop")).get("decks")).getFirst().get("cards")).getFirst(),"assetId");
        assertEquals("TABLETOP",boards.kind(f.game,owner).get("gameType"));assertThrows(ApiException.class,()->games.snapshot(f.game,owner));long v=revision(f.game,owner);
        commands.transaction(()->boards.command(f.game,owner,"DRAW",v,obj("deckId","deck")));
        assertThrows(ApiException.class,()->commands.transaction(()->boards.command(f.game,owner,"SHUFFLE",v,obj("deckId","deck"))));
        assertTrue(json.write(boards.snapshot(f.game,owner)).contains("상대에게 보이면 안 되는 카드"));assertFalse(json.write(boards.snapshot(f.game,other)).contains("상대에게 보이면 안 되는 카드"));assertTrue(scenes.canAccessAsset(owner,f.game,null,UUID.fromString(asset)));assertFalse(scenes.canAccessAsset(other,f.game,null,UUID.fromString(asset)));
        commands.transaction(()->games.leaveGame(f.game,owner));assertFalse(scenes.canAccessAsset(owner,f.game,null,UUID.fromString(asset)));assertEquals(other,Db.uuid(db.one("select host_id from room where id=?",f.room),"host_id"));
        commands.transaction(()->boards.command(f.game,other,"FINISH",revision(f.game,other),Map.of()));assertEquals("COMPLETED",boards.snapshot(f.game,other).get("status"));assertEquals(0,((Number)games.history(other,0,20).get("total")).intValue());assertEquals("IDLE",Db.str(db.one("select kind from player_activity where user_id=?",other),"kind"));
    }
    @Test void independentSandboxNeverCreatesActivityOrGameRowsAndUsesIdenticalBoardRules(){
        for(String type:List.of("TABLETOP","YACHT")){var f=start(boardDefinition(type),2,true);UUID actor=f.users.getFirst();long count=((Number)db.one("select count(*) n from game_session").get("n")).longValue();UUID sandbox=commands.transaction(()->UUID.fromString(sandboxes.create(actor,f.version,2).get("id").toString()));assertEquals(count,((Number)db.one("select count(*) n from game_session").get("n")).longValue());assertEquals(f.game,Db.uuid(db.one("select reference_id from player_activity where user_id=?",actor),"reference_id"));assertThrows(ApiException.class,()->sandboxes.snapshot(sandbox,f.users.get(1),0));
            commands.transaction(()->sandboxes.command(sandbox,actor,0,type.equals("YACHT")?"ROLL":"DRAW",1,type.equals("YACHT")?Map.of():obj("deckId","deck")));
            assertThrows(ApiException.class,()->commands.transaction(()->sandboxes.command(sandbox,actor,0,"RESET",1,Map.of())));var snapshot=sandboxes.snapshot(sandbox,actor,0);assertEquals(2L,((Number)snapshot.get("stateVersion")).longValue());
            commands.transaction(()->sandboxes.command(sandbox,actor,0,"RESET",2,Map.of()));assertEquals(3L,((Number)sandboxes.snapshot(sandbox,actor,0).get("stateVersion")).longValue());
        }
    }
    @Test void cardDesignFacesAndAssetAccessAgreeAcrossStoredGameAndSandbox(){
        UUID front=UUID.randomUUID(),unusedBack=UUID.randomUUID(),commonBack=UUID.randomUUID(),legacy=UUID.randomUUID();
        var d=boardDefinition("TABLETOP");var deck=objects(map(d.get("tabletop")).get("decks")).getFirst();var card=objects(deck.get("cards")).getFirst();
        card.put("layoutId","individual");card.put("assetId",legacy.toString());deck.put("backLayoutId","common");deck.put("backAssetId",legacy.toString());
        d.put("presentation",obj("scenes",List.of(),"cardLayouts",List.of(obj("id","individual","name","개별 카드","width",600,"height",850,"front",designFace(front),"back",designFace(unusedBack)),obj("id","common","name","덱 뒷면","width",600,"height",850,"front",designFace(unusedBack),"back",designFace(commonBack)))));
        var f=start(d,2,true);UUID author=f.users.getFirst(),guest=f.users.get(1);UUID sandbox=commands.transaction(()->UUID.fromString(sandboxes.create(author,f.version,2).get("id").toString()));
        assertTrue(scenes.canAccessAsset(guest,f.game,null,commonBack));assertFalse(scenes.canAccessAsset(guest,f.game,null,front));assertFalse(scenes.canAccessAsset(author,null,sandbox,front));assertFalse(scenes.canAccessAsset(guest,f.game,null,unusedBack));assertFalse(scenes.canAccessAsset(guest,f.game,null,legacy));
        commands.transaction(()->boards.command(f.game,guest,"DRAW",revision(f.game,guest),obj("deckId","deck")));sandboxCommand(sandbox,author,1,"DRAW",obj("deckId","deck"));
        var actualCard=objects(map(boards.snapshot(f.game,guest).get("state")).get("objects")).getFirst();var virtualCard=objects(map(sandboxes.snapshot(sandbox,author,1).get("state")).get("objects")).getFirst();
        assertEquals(actualCard.get("faceDesign"),virtualCard.get("faceDesign"));assertEquals(120,actualCard.get("width"));assertEquals(170,actualCard.get("height"));assertTrue(scenes.canAccessAsset(guest,f.game,null,front));assertFalse(scenes.canAccessAsset(author,f.game,null,front));assertTrue(scenes.canAccessAsset(author,null,sandbox,front));
        commands.transaction(()->boards.command(f.game,guest,"TRANSFER",revision(f.game,guest),obj("objectId",actualCard.get("id"),"toSeat",null)));sandboxCommand(sandbox,author,1,"TRANSFER",obj("objectId",virtualCard.get("id"),"toSeat",null));
        assertFalse(scenes.canAccessAsset(guest,f.game,null,front));assertFalse(scenes.canAccessAsset(author,null,sandbox,front));assertFalse(scenes.canAccessAsset(guest,f.game,null,legacy));
        assertEquals(objects(map(boards.snapshot(f.game,author).get("state")).get("objects")).getFirst().get("faceDesign"),objects(map(sandboxes.snapshot(sandbox,author,0).get("state")).get("objects")).getFirst().get("faceDesign"));
        commands.transaction(()->boards.command(f.game,author,"FLIP",revision(f.game,author),obj("objectId",actualCard.get("id"))));sandboxCommand(sandbox,author,0,"FLIP",obj("objectId",virtualCard.get("id")));
        for(UUID user:f.users)assertTrue(scenes.canAccessAsset(user,f.game,null,front));assertTrue(scenes.canAccessAsset(author,null,sandbox,front));
        var wire=json.write(boards.snapshot(f.game,guest));for(String value:List.of("layoutId","backLayoutId","editor-card-node","editor-secret","definitionId",legacy.toString(),unusedBack.toString()))assertFalse(wire.contains(value),value);
    }
    private Map<String,Object> designFace(UUID asset){return obj("background","#ffffff","nodes",List.of(obj("id","editor-card-node","kind","IMAGE","x",0,"y",0,"width",600,"height",850,"rotation",0,"assetId",asset.toString(),"hidden",true,"locked",true,"metadata","editor-secret")));}
    @Test void concurrentCardDrawAndMoveHaveOneWinnerAndRetryDoesNotRepeatTheAction()throws Exception{
        var f=start(boardDefinition("TABLETOP"),2,true);UUID actor=f.users.getFirst();long before=revision(f.game,actor);var draw=obj("type","DRAW","expectedVersion",before,"payload",obj("deckId","deck"));String first=UUID.randomUUID().toString(),second=UUID.randomUUID().toString();var ready=new CountDownLatch(1);
        List<String> results;try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->concurrentCommand(ready,actor,f.game,first,draw));var b=pool.submit(()->concurrentCommand(ready,actor,f.game,second,draw));ready.countDown();results=List.of(a.get(10,TimeUnit.SECONDS),b.get(10,TimeUnit.SECONDS));}
        assertEquals(1,results.stream().filter("OK"::equals).count());assertEquals(1,results.stream().filter("STALE_STATE"::equals).count());String winner=results.getFirst().equals("OK")?first:second;
        var snapshot=boards.snapshot(f.game,actor);var state=map(snapshot.get("state"));assertEquals(0,integer(objects(state.get("decks")).getFirst(),"count",-1));assertEquals(1,objects(state.get("objects")).size());assertEquals(before+1,((Number)snapshot.get("stateVersion")).longValue());
        assertEquals("OK",concurrentCommand(new CountDownLatch(0),actor,f.game,winner,draw));assertEquals(before+1,revision(f.game,actor));String cached=db.one("select result::text value from command_result where user_id=? and key=?",actor,winner).get("value").toString();assertFalse(cached.contains("assetId"));assertFalse(cached.contains("비밀"));
        String card=str(objects(state.get("objects")).getFirst(),"id");long moveVersion=revision(f.game,actor);var moveA=obj("type","MOVE","expectedVersion",moveVersion,"payload",obj("objectId",card,"x",10,"y",20));var moveB=obj("type","MOVE","expectedVersion",moveVersion,"payload",obj("objectId",card,"x",90,"y",80));var moveReady=new CountDownLatch(1);
        try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->concurrentCommand(moveReady,actor,f.game,UUID.randomUUID().toString(),moveA));var b=pool.submit(()->concurrentCommand(moveReady,actor,f.game,UUID.randomUUID().toString(),moveB));moveReady.countDown();var moves=List.of(a.get(10,TimeUnit.SECONDS),b.get(10,TimeUnit.SECONDS));assertEquals(1,moves.stream().filter("OK"::equals).count());assertEquals(1,moves.stream().filter("STALE_STATE"::equals).count());}
        assertEquals(moveVersion+1,revision(f.game,actor));var moved=objects(map(boards.snapshot(f.game,actor).get("state")).get("objects")).getFirst();assertTrue(Set.of(10,90).contains(((Number)moved.get("x")).intValue()));
    }
    @Test void onePlayerYachtFinishesTwelveCategoriesAndKeepsServerRankingInHistory(){
        var definition=boardDefinition("YACHT");definition.put("playerCount",1);definition.put("supportedPlayerCounts",List.of(1));var f=start(definition,1,false);UUID player=f.users.getFirst();
        for(String category:BoardEngine.CATEGORIES){commands.transaction(()->boards.command(f.game,player,"ROLL",revision(f.game,player),Map.of()));assertTrue(map(map(boards.snapshot(f.game,player).get("state")).get("availableScores")).containsKey(category));commands.transaction(()->boards.command(f.game,player,"SCORE",revision(f.game,player),obj("category",category)));}
        var snapshot=boards.snapshot(f.game,player);assertEquals("COMPLETED",snapshot.get("status"));var state=map(snapshot.get("state"));assertEquals(List.of(0),state.get("winners"));assertEquals(1L,objects(state.get("scores")).getFirst().get("rank"));assertEquals(12,map(objects(state.get("scores")).getFirst().get("categories")).size());assertEquals(1,((Number)games.history(player,0,20).get("total")).intValue());assertEquals("IDLE",db.one("select kind from player_activity where user_id=?",player).get("kind"));
    }
    @Test void tabletopManualCounterSurvivesFinishAndFreshSnapshot(){var d=boardDefinition("TABLETOP");map(d.get("tabletop")).put("objects",List.of(obj("id","score","kind","COUNTER","name","수동 점수","value",0,"x",0,"y",0,"width",100,"height",60,"faceUp",true,"locked",false)));var f=start(d,2,false);UUID host=f.users.getFirst();commands.transaction(()->boards.command(f.game,host,"COUNTER",revision(f.game,host),obj("objectId","score","value",37)));commands.transaction(()->boards.command(f.game,host,"FINISH",revision(f.game,host),Map.of()));var snapshot=boards.snapshot(f.game,f.users.get(1));assertEquals("COMPLETED",snapshot.get("status"));var state=map(snapshot.get("state"));assertTrue(bool(state,"finished"));assertEquals(37,integer(objects(state.get("objects")).getFirst(),"value",0));}
    @Test void boardAbortUsesSameUnanimityAndReleasePolicyAsMystery(){var f=start(boardDefinition("YACHT"),2,false);UUID a=f.users.getFirst(),b=f.users.get(1);var initial=boards.snapshot(f.game,a);assertEquals("AUTOMATIC",initial.get("resultKind"));assertEquals(2,initial.get("abortRequired"));assertEquals(true,initial.get("canRequestAbort"));commands.transaction(()->games.abortVote(f.game,a));assertEquals(1L,boards.snapshot(f.game,b).get("abortVotes"));assertEquals("ACTIVE",boards.snapshot(f.game,b).get("status"));commands.transaction(()->games.abortVote(f.game,b));var aborted=boards.snapshot(f.game,a);assertEquals("ABORTED",aborted.get("status"));assertEquals(false,aborted.get("canRequestAbort"));var state=map(aborted.get("state"));assertTrue(bool(state,"finished"));assertTrue(((List<?>)state.get("winners")).isEmpty());assertNull(objects(state.get("scores")).getFirst().get("rank"));assertEquals("IDLE",db.one("select kind from player_activity where user_id=?",a).get("kind"));assertEquals("ABORTED",objects(games.history(a,0,20).get("items")).getFirst().get("status"));}
    @Test void classicGamesShareLegalMovesAndStateAcrossRealPostgresAndSandboxAndResignation(){
        for(String type:List.of("GOMOKU","REVERSI","CHECKERS")){var d=classicDefinition(type);var f=start(d,2,true);UUID author=f.users.getFirst();UUID sandbox=commands.transaction(()->UUID.fromString(sandboxes.create(author,f.version,2).get("id").toString()));
            for(int step=0;step<10;step++){var current=map(boards.snapshot(f.game,author).get("state"));if(bool(current,"finished"))break;int seat=integer(current,"turnSeat",0);UUID actor=f.users.get(seat);var actual=map(boards.snapshot(f.game,actor).get("state"));var simulated=map(sandboxes.snapshot(sandbox,author,seat).get("state"));assertEquals(actual,simulated);var legal=objects(actual.get("legalMoves"));assertFalse(legal.isEmpty());var move=legal.getFirst();String command=type.equals("CHECKERS")?"MOVE":"PLACE";Map<String,Object> payload=type.equals("CHECKERS")?obj("fromRow",move.get("fromRow"),"fromCol",move.get("fromCol"),"toRow",move.get("row"),"toCol",move.get("col")):obj("row",move.get("row"),"col",move.get("col"));
                commands.transaction(()->boards.command(f.game,actor,command,revision(f.game,actor),payload));sandboxCommand(sandbox,author,seat,command,payload);for(int view=0;view<2;view++)assertEquals(map(boards.snapshot(f.game,f.users.get(view)).get("state")),map(sandboxes.snapshot(sandbox,author,view).get("state")));
            }
            if(!bool(map(boards.snapshot(f.game,author).get("state")),"finished")){commands.transaction(()->games.leaveGame(f.game,f.users.get(1)));sandboxCommand(sandbox,author,1,"LEAVE",Map.of());var actual=boards.snapshot(f.game,author);assertEquals("COMPLETED",actual.get("status"));assertEquals("AUTOMATIC",actual.get("resultKind"));assertEquals(List.of(0),map(actual.get("state")).get("winners"));assertEquals("RESIGNATION",map(actual.get("state")).get("endReason"));assertEquals(map(actual.get("state")),map(sandboxes.snapshot(sandbox,author,0).get("state")));assertThrows(ApiException.class,()->boards.snapshot(f.game,f.users.get(1)));}
        }
    }
    @Test void classicAbortNeverAwardsAResignationWin(){for(String type:List.of("GOMOKU","REVERSI","CHECKERS")){var f=start(classicDefinition(type),2,true);commands.transaction(()->games.abortVote(f.game,f.users.getFirst()));commands.transaction(()->games.abortVote(f.game,f.users.get(1)));var snapshot=boards.snapshot(f.game,f.users.getFirst());var state=map(snapshot.get("state"));assertEquals("ABORTED",snapshot.get("status"));assertEquals("ABORTED",state.get("endReason"));assertEquals(List.of(),state.get("winners"));assertEquals(false,state.get("draw"));}}
    private Map<String,Object> classicDefinition(String type){return obj("gameType",type,"engineId",type.toLowerCase(Locale.ROOT)+"-v1","playerCount",2,"supportedPlayerCounts",List.of(2),"classic",obj("boardColor","#d9ad6a","lightSquareColor","#f4e4c1","darkSquareColor","#486b46","firstPieceColor","#242a27","secondPieceColor","#fffaf0"));}
    private String concurrentCommand(CountDownLatch start,UUID actor,UUID game,String key,Map<String,Object> body)throws InterruptedException{start.await();try{commands.run(actor,key,"test.board:"+game,body,()->boards.command(game,actor,str(body,"type"),((Number)body.get("expectedVersion")).longValue(),map(body.get("payload"))),result->boards.authorize(game,actor));return "OK";}catch(ApiException e){return e.code;}}
    @Test void sceneSwitchCannotRevealAnotherRoleOrFuturePhaseAssetAndHostSuccessionWorks()throws Exception{
        Map<String,Object> d;try(var stream=getClass().getResourceAsStream("/scenarios/snowbound-last-parcel.json")){d=json.object(new String(Objects.requireNonNull(stream).readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));}
        var roles=objects(d.get("roles"));String firstPhase=str(objects(d.get("phases")).getFirst(),"id"),lastPhase=str(objects(d.get("phases")).getLast(),"id");UUID privateAsset=UUID.randomUUID(),futureAsset=UUID.randomUUID();
        d.put("presentation",obj("scenes",List.of(obj("id","opening","name","도입","kind","SCENE","phaseIds",List.of(firstPhase),"nodes",List.of()),obj("id","alternate","name","다른 도입","kind","SCENE","phaseIds",List.of(firstPhase),"nodes",List.of()),obj("id","ending-art","name","결말","kind","SCENE","phaseIds",List.of(lastPhase),"bgmAssetId",futureAsset.toString(),"nodes",List.of()),obj("id","private-layout","name","역할 자료","kind","ROLE","referenceId",roles.getFirst().get("id"),"phaseIds",List.of(),"nodes",List.of(obj("id","private-node","kind","IMAGE","bindingType","NONE","assetId",privateAsset.toString()))))));
        var f=start(d,2,true);UUID host=f.users.getFirst(),guest=f.users.get(1);UUID privateUser=f.users.stream().filter(u->str(games.role(f.game,u),"id").equals(str(roles.getFirst(),"id"))).findFirst().orElseThrow();UUID other=privateUser.equals(host)?guest:host;
        assertTrue(scenes.canAccessAsset(privateUser,f.game,null,privateAsset));assertFalse(scenes.canAccessAsset(other,f.game,null,privateAsset));assertFalse(scenes.canAccessAsset(host,f.game,null,futureAsset));
        assertThrows(ApiException.class,()->commands.transaction(()->boards.changeScene(f.game,guest,"alternate")));assertThrows(ApiException.class,()->commands.transaction(()->boards.changeScene(f.game,host,"ending-art")));
        commands.transaction(()->boards.changeScene(f.game,host,"alternate"));assertEquals("alternate",map(games.snapshot(f.game,guest).get("scene")).get("id"));assertEquals(firstPhase,map(games.snapshot(f.game,guest).get("phase")).get("definitionId"));
        commands.transaction(()->games.leaveGame(f.game,host));assertEquals(guest,Db.uuid(db.one("select host_id from room where id=?",f.room),"host_id"));commands.transaction(()->boards.changeScene(f.game,guest,"opening"));assertFalse(scenes.canAccessAsset(host,f.game,null,privateAsset));
        commands.transaction(()->{db.update("update phase_instance set ends_at=? where id=(select current_phase_id from game_session where id=?)",Instant.now().minusSeconds(1),f.game);games.tick();return null;});assertNull(games.snapshot(f.game,guest).get("scene"));assertNull(db.one("select active_scene_id from game_session where id=?",f.game).get("active_scene_id"));
    }
    @Test void murderMysterySandboxAndActualGameAgreeForEveryPhaseInvestigationVoteAndEnding()throws Exception{
        for(String story:List.of("locker-at-twelve","snowbound-last-parcel","after-hours-gallery")){
            Map<String,Object> definition;try(var stream=getClass().getResourceAsStream("/scenarios/"+story+".json")){definition=json.object(new String(Objects.requireNonNull(stream).readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));}
            var f=start(definition,integer(definition,"playerCount",0),true);UUID author=f.users.getFirst();UUID sandbox=commands.transaction(()->UUID.fromString(sandboxes.create(author,f.version,f.users.size()).get("id").toString()));var roles=objects(definition.get("roles"));var seats=new HashMap<UUID,Integer>();for(UUID user:f.users){String rid=str(games.role(f.game,user),"id");for(int i=0;i<roles.size();i++)if(str(roles.get(i),"id").equals(rid))seats.put(user,i);}
            for(int phase=0;phase<objects(definition.get("phases")).size();phase++){
                for(UUID user:f.users){var actual=games.snapshot(f.game,user);var simulated=map(sandboxes.snapshot(sandbox,author,seats.get(user)).get("state"));assertEquals(actual.get("myRole"),simulated.get("myRole"));assertEquals(map(actual.get("phase")).get("definitionId"),map(simulated.get("phase")).get("definitionId"));assertEquals(actual.get("clues"),simulated.get("clues"));assertEquals(actual.get("ending"),simulated.get("ending"));assertEquals(objects(actual.get("materials")).stream().map(m->m.get("text")).sorted(Comparator.comparing(Object::toString)).toList(),objects(simulated.get("materials")).stream().map(m->m.get("text")).sorted(Comparator.comparing(Object::toString)).toList());}
                var phaseDef=objects(definition.get("phases")).get(phase);if(strings(phaseDef.get("actions")).contains("INVESTIGATE"))for(UUID user:f.users){var actual=games.snapshot(f.game,user);for(var target:objects(actual.get("targets"))){if((int)games.snapshot(f.game,user).get("investigationsRemaining")<=0)break;commands.transaction(()->games.investigate(f.game,user,str(target,"id")));sandboxCommand(sandbox,author,seats.get(user),"INVESTIGATE",obj("targetId",target.get("id")));}}
                if(strings(phaseDef.get("actions")).contains("SHARE"))for(UUID user:f.users)for(var clue:objects(games.snapshot(f.game,user).get("clues")))if(bool(clue,"owned")&&!str(clue,"sharePolicy").equals("PRIVATE")){commands.transaction(()->games.share(f.game,user,str(clue,"id"),"PUBLIC",null));sandboxCommand(sandbox,author,seats.get(user),"SHARE",obj("clueId",clue.get("id"),"scope","PUBLIC"));}
                if(str(phaseDef,"kind").equals("VOTE"))for(UUID user:f.users){UUID ballot=UUID.fromString(str(map(games.snapshot(f.game,user).get("ballot")),"id"));String culprit=str(map(definition.get("ballot")),"culpritRoleId");commands.transaction(()->games.vote(f.game,user,ballot,culprit));sandboxCommand(sandbox,author,seats.get(user),"VOTE",obj("roleId",culprit));}
                if(str(phaseDef,"kind").equals("READING")){for(UUID user:f.users){commands.transaction(()->games.phaseReady(f.game,user));sandboxCommand(sandbox,author,seats.get(user),"PHASE_READY",Map.of());}}
                else {commands.transaction(()->{db.update("update phase_instance set ends_at=? where id=(select current_phase_id from game_session where id=?)",Instant.now().minusSeconds(1),f.game);games.tick();return null;});sandboxCommand(sandbox,author,0,"ADVANCE_TIME",Map.of());}
            }
            assertEquals("COMPLETED",games.snapshot(f.game,author).get("status"));assertEquals("COMPLETED",map(sandboxes.snapshot(sandbox,author,0).get("state")).get("status"));assertEquals(0,((Number)games.history(author,0,20).get("total")).intValue());assertEquals(f.users.size(),Db.num(db.one("select count(*) n from scenario_exposure_source where version_id=? and source='TEST_PLAY'",f.version),"n"));
        }
    }
    private void sandboxCommand(UUID id,UUID actor,int seat,String type,Map<String,Object> payload){long revision=((Number)sandboxes.snapshot(id,actor,seat).get("stateVersion")).longValue();commands.transaction(()->sandboxes.command(id,actor,seat,type,revision,payload));}
}
